import importlib
import pickle
import uuid

import pytest

import bedrock_protocol
from bedrock_protocol import v2193 as proto

# generated by gophertunnel b8bd735:
# packet.Header{PacketID: 2, SenderSubClient: 1, TargetSubClient: 2} then
# packet.PlayStatus{Status: packet.PlayStatusPlayerSpawn}
FRAMED_PLAY_STATUS = bytes.fromhex("824800000003")

PLAY_STATUS = proto.PlayStatusPacket(status=proto.PlayStatus.PLAYER_SPAWN)

HEALTH = proto.AttributeData(name="health")
TRUNCATED_ATTRIBUTES = bytes(proto.UpdateAttributesPacket(attribute_data=[HEALTH, HEALTH]))[:-2]


def test_the_bare_names_are_the_latest_protocol():
    latest = importlib.import_module(f"bedrock_protocol.v{bedrock_protocol.VERSIONS[-1]}")
    assert bedrock_protocol.TextPacket is latest.TextPacket


def test_the_bare_names_are_the_latest_versions_all():
    latest = importlib.import_module(f"bedrock_protocol.v{bedrock_protocol.VERSIONS[-1]}")
    assert set(bedrock_protocol.__all__) == {"VERSIONS", "DecodeError", "PacketHeader", "nbt", *latest.__all__}


def test_the_package_has_no_pre_cereal():
    assert not hasattr(bedrock_protocol, "pre_cereal")


def test_a_version_leaves_pre_cereal_out_of_its_all(protocol):
    assert "pre_cereal" not in protocol.__all__


def test_the_bare_protocol_number_is_the_latest_protocol():
    assert bedrock_protocol.VERSIONS[-1] == bedrock_protocol.PROTOCOL


def test_the_bare_codec_round_trips_a_packet():
    packet = bedrock_protocol.PlayStatusPacket(status=bedrock_protocol.PlayStatus.PLAYER_SPAWN)
    assert bedrock_protocol.decode(packet.ID, bedrock_protocol.encode(packet)) == packet


def test_the_header_packs_recipient_then_sender_as_bds_does():
    assert proto.encode_packet(PLAY_STATUS, recipient_sub_id=1, sender_sub_id=2) == FRAMED_PLAY_STATUS


def test_the_header_unpacks_recipient_then_sender_as_bds_does():
    header, _ = proto.decode_packet(FRAMED_PLAY_STATUS)
    assert (header.packet_id, header.recipient_sub_id, header.sender_sub_id) == (PLAY_STATUS.ID, 1, 2)


def test_a_framed_packet_decodes_to_its_body():
    _, packet = proto.decode_packet(FRAMED_PLAY_STATUS)
    assert packet == PLAY_STATUS


def test_positionals_fill_fields_in_order_and_keywords_by_name():
    assert proto.Vec3(1, 2, z=3) == proto.Vec3(x=1, y=2, z=3)


def test_a_positional_and_a_keyword_for_one_field_are_rejected():
    with pytest.raises(TypeError, match="multiple values"):
        proto.Vec3(1, x=2)


def test_a_keyword_the_schema_does_not_name_is_rejected():
    with pytest.raises(TypeError, match="no field 'w'"):
        proto.Vec3(w=1)


def test_more_positionals_than_fields_are_rejected():
    with pytest.raises(TypeError, match="at most 3"):
        proto.Vec3(1, 2, 3, 4)


def test_a_struct_field_is_a_live_reference():
    packet = proto.MovePlayerPacket()
    pos = packet.pos
    packet.pos.x = 5.5
    assert pos.x == 5.5


def test_a_list_field_is_a_copy():
    packet = proto.PlayerAuthInputPacket(input_data=[proto.PlayerAuthInputPacket.InputData.UP])
    packet.input_data.append(proto.PlayerAuthInputPacket.InputData.DOWN)
    assert packet.input_data == [proto.PlayerAuthInputPacket.InputData.UP]


@pytest.fixture
def unnamed_status():
    return proto.PlayStatusPacket.from_bytes(bytes([0, 0, 0, 0xFF]))


def test_a_value_the_schema_does_not_name_crosses_as_an_int(unnamed_status):
    assert type(unnamed_status.status) is int
    assert unnamed_status.status == 255


def test_a_value_the_schema_does_not_name_shows_in_the_repr(unnamed_status):
    assert "status=255" in repr(unnamed_status)


def test_a_value_the_schema_does_not_name_encodes_again(unnamed_status):
    assert bytes(unnamed_status) == bytes([0, 0, 0, 0xFF])


def test_an_enum_value_its_cpp_type_cannot_hold_is_rejected():
    with pytest.raises(
        bedrock_protocol.DecodeError,
        match=r"^RequestPermissionsPacket\.player_permissions: out of range at byte 10 of 12$",
    ):
        proto.RequestPermissionsPacket.from_bytes(bytes(8) + b"\xd8\x04" + bytes(2))


def test_a_name_the_schema_does_not_hold_is_rejected():
    with pytest.raises(bedrock_protocol.DecodeError, match=r"^CommandOutput\.type: unknown value at byte 5 of 5$"):
        proto.CommandOutput.from_bytes(b"\x04nope")


def test_a_container_id_the_schema_does_not_name_round_trips():
    window = proto.ContainerClosePacket(container_id=5)
    assert proto.ContainerClosePacket.from_bytes(bytes(window)) == window


def test_a_named_value_assigned_to_an_int_field_comes_back_as_the_enum_member():
    window = proto.ContainerClosePacket(container_id=5)
    window.container_id = proto.ContainerID.INVENTORY
    assert window.container_id is proto.ContainerID.INVENTORY


def test_a_value_that_does_not_fit_the_enum_is_rejected():
    with pytest.raises(TypeError, match="does not fit the enum"):
        proto.ContainerClosePacket(container_id=1000)


def test_a_bytes_field_crosses_as_python_bytes():
    packet = proto.LevelChunkPacket(serialized_chunk=bytes([0xFF, 0x00, 0xC3, 0x41]))
    assert packet.serialized_chunk == bytes([0xFF, 0x00, 0xC3, 0x41])


def test_a_bytes_field_round_trips():
    packet = proto.LevelChunkPacket(serialized_chunk=bytes([0xFF, 0x00, 0xC3, 0x41]))
    assert proto.LevelChunkPacket.from_bytes(bytes(packet)) == packet


def test_a_bytes_field_rejects_text():
    with pytest.raises(TypeError, match=r"^LevelChunkPacket\.serialized_chunk cannot hold 'héllo'$"):
        proto.LevelChunkPacket(serialized_chunk="héllo")


def test_a_string_field_rejects_bytes():
    with pytest.raises(TypeError, match=r"^ResourcePackChunkDataPacket\.resource_name cannot hold b'p'$"):
        proto.ResourcePackChunkDataPacket(resource_name=b"p")


def test_a_string_carries_wire_bytes_that_are_not_utf8():
    text = b"\xff".decode("utf-8", "surrogateescape")
    packet = proto.ResourcePackChunkDataPacket(resource_name=text)
    assert proto.ResourcePackChunkDataPacket.from_bytes(bytes(packet)).resource_name == text


def test_a_string_can_be_assigned_text():
    packet = proto.ResourcePackChunkDataPacket()
    packet.resource_name = "héllo"
    assert packet.resource_name == "héllo"


def test_a_uuid_crosses_as_uuid():
    value = uuid.UUID("12345678-9abc-def0-1122-334455667788")
    request = proto.CommandRequestPacket().origin
    request.uuid = value
    assert request.uuid == value
    assert type(request).from_bytes(bytes(request)).uuid == value


def test_a_python_keyword_member_keeps_the_dsl_underscore():
    assert "pass_" in proto.BiomeConsolidatedFeatureData.__match_args__


def test_decode_rejects_trailing_bytes():
    with pytest.raises(bedrock_protocol.DecodeError, match=r"^PlayStatusPacket: trailing bytes at byte 4 of 5$"):
        proto.decode(PLAY_STATUS.ID, bytes(PLAY_STATUS) + b"\x00")


def test_decode_rejects_a_truncated_body():
    with pytest.raises(bedrock_protocol.DecodeError, match=r"^PlayStatusPacket.status: truncated at byte 0 of 3$"):
        proto.decode(PLAY_STATUS.ID, bytes(PLAY_STATUS)[:-1])


def test_a_decode_error_is_a_value_error():
    with pytest.raises(ValueError, match="truncated"):
        proto.UpdateAttributesPacket.from_bytes(TRUNCATED_ATTRIBUTES)


def test_a_decode_error_built_in_python_carries_its_fields():
    error = bedrock_protocol.DecodeError("message", "truncated", ("a", 1), 7)
    assert (str(error), error.reason, error.path, error.offset) == ("message", "truncated", ("a", 1), 7)


def test_a_decode_error_pickles_with_its_fields():
    error = pickle.loads(pickle.dumps(bedrock_protocol.DecodeError("message", "truncated", ("a", 1), 7)))
    assert (str(error), error.reason, error.path, error.offset) == ("message", "truncated", ("a", 1), 7)


def test_a_decode_error_carries_its_reason():
    with pytest.raises(bedrock_protocol.DecodeError, match="truncated") as caught:
        proto.UpdateAttributesPacket.from_bytes(TRUNCATED_ATTRIBUTES)
    assert caught.value.reason == "truncated"


def test_a_decode_error_carries_the_path_through_a_list_element():
    with pytest.raises(bedrock_protocol.DecodeError, match="truncated") as caught:
        proto.UpdateAttributesPacket.from_bytes(TRUNCATED_ATTRIBUTES)
    assert caught.value.path == ("attribute_data", 1, "modifiers")


def test_a_decode_error_carries_the_offset_where_the_reader_stopped():
    with pytest.raises(bedrock_protocol.DecodeError, match="truncated") as caught:
        proto.UpdateAttributesPacket.from_bytes(TRUNCATED_ATTRIBUTES)
    assert caught.value.offset == 65


def test_a_decode_error_message_names_the_nested_field_and_the_list_element():
    with pytest.raises(
        bedrock_protocol.DecodeError,
        match=r"^UpdateAttributesPacket\.attribute_data\[1\]\.modifiers: truncated at byte 65 of 65$",
    ):
        proto.UpdateAttributesPacket.from_bytes(TRUNCATED_ATTRIBUTES)


def test_a_rejected_value_reports_the_offset_after_it():
    with pytest.raises(
        bedrock_protocol.DecodeError,
        match=r"^ItemStackResponseSlotInfo\.durability_correction: out of range at byte 9 of 10$",
    ):
        proto.ItemStackResponseSlotInfo.from_bytes(bytes(6) + bytes.fromhex("808004") + b"\x00")


@pytest.mark.parametrize(
    ("decode", "data", "message"),
    [
        pytest.param(
            proto.DataItemBytePayload,
            b"\x01\x00",
            r"^DataItemBytePayload\.type: unknown value at byte 1 of 2$",
            id="unknown value",
        ),
        pytest.param(
            proto.UpdateAttributesPacket,
            bytes.fromhex("00ffffffff0f"),
            r"^UpdateAttributesPacket\.attribute_data: too large at byte 6 of 6$",
            id="too large",
        ),
        pytest.param(
            proto.BlockActorDataPacket,
            bytes(3) + b"\x0a\x00" + b"\x0a\x01a" * 128 + bytes(129),
            r"^BlockActorDataPacket\.data: too deep at byte 389 of 518$",
            id="too deep",
        ),
    ],
)
def test_a_decode_error_message_spells_its_reason(decode, data, message):
    with pytest.raises(bedrock_protocol.DecodeError, match=message):
        decode.from_bytes(data)


def test_a_header_read_fails_as_a_decode_error():
    with pytest.raises(bedrock_protocol.DecodeError, match=r"^PacketHeader: truncated at byte 0 of 0$"):
        proto.decode_packet(b"")


def test_a_decode_error_spells_a_keyword_field_as_python_does():
    with pytest.raises(
        bedrock_protocol.DecodeError, match=r"^BiomeConsolidatedFeatureData\.pass_: truncated"
    ) as caught:
        proto.BiomeConsolidatedFeatureData.from_bytes(bytes(proto.BiomeConsolidatedFeatureData())[:-2])
    assert caught.value.path == ("pass_",)


def test_decode_rejects_an_unknown_packet_id():
    with pytest.raises(KeyError, match="no packet 1023"):
        proto.decode(1023, b"")


@pytest.mark.parametrize(
    ("packet_id", "cls"), proto.PACKETS.items(), ids=lambda value: getattr(value, "__name__", str(value))
)
def test_every_packet_class_is_registered_under_its_id(packet_id, cls):
    assert packet_id == cls.ID


def test_a_header_round_trips_through_its_bytes():
    header, _ = proto.decode_packet(FRAMED_PLAY_STATUS)
    assert bedrock_protocol.PacketHeader.from_bytes(bytes(header)) == header


def test_every_version_frames_with_the_package_header(protocol):
    header, _ = protocol.decode_packet(protocol.encode_packet(protocol.PlayStatusPacket()))
    assert type(header) is bedrock_protocol.PacketHeader


def test_a_pre_cereal_submodule_imports_by_its_dotted_name(protocol):
    assert importlib.import_module(f"{protocol.__name__}.pre_cereal") is protocol.pre_cereal


def test_the_bound_versions_ascend():
    assert list(bedrock_protocol.VERSIONS) == sorted(bedrock_protocol.VERSIONS)


def test_a_shared_class_belongs_to_the_newest_version():
    assert proto.PlayStatusPacket.__module__ == f"bedrock_protocol.v{bedrock_protocol.VERSIONS[-1]}"
